// Package calc evaluates 64-bit signed integer expressions, one per line.
//
// See the calc section of SPEC.md for the exact input and output formats.
package calc

import (
	"bufio"
	"bytes"
	"errors"
	"io"
	"math"
	"strconv"
)

// Errors reported by Eval. Run prints all of them as "error".
var (
	ErrSyntax    = errors.New("syntax error")
	ErrDivByZero = errors.New("division by zero")
	ErrOverflow  = errors.New("integer overflow")
)

// Run reads the whole calc input from r and writes the results to w.
// w is buffered by the caller, which flushes it after Run returns.
func Run(r io.Reader, w io.Writer) error {
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 64<<10), math.MaxInt)
	sc.Split(scanLines)
	var buf []byte
	for sc.Scan() {
		line := sc.Bytes()
		if isBlank(line) {
			continue
		}
		v, err := Eval(line)
		switch {
		case err != nil:
			buf = append(buf[:0], "error\n"...)
		default:
			buf = strconv.AppendInt(buf[:0], v, 10)
			buf = append(buf, '\n')
		}
		if _, err := w.Write(buf); err != nil {
			return err
		}
	}
	return sc.Err()
}

// scanLines is like bufio.ScanLines but keeps a trailing '\r', which is not
// part of the grammar and so makes the expression a syntax error.
func scanLines(data []byte, atEOF bool) (advance int, token []byte, err error) {
	if i := bytes.IndexByte(data, '\n'); i >= 0 {
		return i + 1, data[:i], nil
	}
	if atEOF && len(data) > 0 {
		return len(data), data, nil
	}
	return 0, nil, nil
}

// isBlank reports whether line holds only spaces and tabs.
func isBlank(line []byte) bool {
	for _, c := range line {
		if c != ' ' && c != '\t' {
			return false
		}
	}
	return true
}

// Eval evaluates a single expression. It returns ErrSyntax, ErrDivByZero or
// ErrOverflow on failure.
func Eval(line []byte) (int64, error) {
	p := parser{src: line}
	v, err := p.expr()
	if err != nil {
		return 0, err
	}
	if p.peek() != 0 {
		return 0, ErrSyntax
	}
	return v, nil
}

// parser is a recursive-descent evaluator over one line of input.
type parser struct {
	src []byte
	pos int
}

// peek skips blanks and returns the next byte without consuming it,
// or 0 at end of input.
func (p *parser) peek() byte {
	for p.pos < len(p.src) && (p.src[p.pos] == ' ' || p.src[p.pos] == '\t') {
		p.pos++
	}
	if p.pos == len(p.src) {
		return 0
	}
	return p.src[p.pos]
}

// expr := term (('+' | '-') term)*
func (p *parser) expr() (int64, error) {
	v, err := p.term()
	if err != nil {
		return 0, err
	}
	for {
		op := p.peek()
		if op != '+' && op != '-' {
			return v, nil
		}
		p.pos++
		rhs, err := p.term()
		if err != nil {
			return 0, err
		}
		if op == '+' {
			v, err = add(v, rhs)
		} else {
			v, err = sub(v, rhs)
		}
		if err != nil {
			return 0, err
		}
	}
}

// term := unary (('*' | '/' | '%') unary)*
func (p *parser) term() (int64, error) {
	v, err := p.unary()
	if err != nil {
		return 0, err
	}
	for {
		op := p.peek()
		if op != '*' && op != '/' && op != '%' {
			return v, nil
		}
		p.pos++
		rhs, err := p.unary()
		if err != nil {
			return 0, err
		}
		switch op {
		case '*':
			v, err = mul(v, rhs)
		case '/':
			v, err = div(v, rhs)
		default:
			v, err = rem(v, rhs)
		}
		if err != nil {
			return 0, err
		}
	}
}

// unary := '-' unary | primary
//
// Chains of '-' are counted iteratively so long runs cannot exhaust the stack.
func (p *parser) unary() (int64, error) {
	negs := 0
	for p.peek() == '-' {
		p.pos++
		negs++
	}
	v, err := p.primary()
	if err != nil {
		return 0, err
	}
	if negs == 0 {
		return v, nil
	}
	// Only the innermost negation can overflow; later ones operate on a
	// value whose negation is always representable.
	if v == math.MinInt64 {
		return 0, ErrOverflow
	}
	if negs%2 == 1 {
		v = -v
	}
	return v, nil
}

// primary := NUMBER | '(' expr ')'
func (p *parser) primary() (int64, error) {
	c := p.peek()
	switch {
	case c == '(':
		p.pos++
		v, err := p.expr()
		if err != nil {
			return 0, err
		}
		if p.peek() != ')' {
			return 0, ErrSyntax
		}
		p.pos++
		return v, nil
	case isDigit(c):
		return p.number()
	default:
		return 0, ErrSyntax
	}
}

// number parses NUMBER := [0-9]+ at the current position.
func (p *parser) number() (int64, error) {
	var v int64
	overflow := false
	for p.pos < len(p.src) && isDigit(p.src[p.pos]) {
		d := int64(p.src[p.pos] - '0')
		p.pos++
		if overflow || v > (math.MaxInt64-d)/10 {
			overflow = true
			continue
		}
		v = v*10 + d
	}
	if overflow {
		return 0, ErrOverflow
	}
	return v, nil
}

func isDigit(c byte) bool { return '0' <= c && c <= '9' }

func add(a, b int64) (int64, error) {
	s := a + b
	if (a >= 0) == (b >= 0) && (s >= 0) != (a >= 0) {
		return 0, ErrOverflow
	}
	return s, nil
}

func sub(a, b int64) (int64, error) {
	d := a - b
	if (a >= 0) != (b >= 0) && (d >= 0) != (a >= 0) {
		return 0, ErrOverflow
	}
	return d, nil
}

func mul(a, b int64) (int64, error) {
	if a == 0 || b == 0 {
		return 0, nil
	}
	p := a * b
	if (a == -1 && b == math.MinInt64) || (b == -1 && a == math.MinInt64) || p/b != a {
		return 0, ErrOverflow
	}
	return p, nil
}

func div(a, b int64) (int64, error) {
	if b == 0 {
		return 0, ErrDivByZero
	}
	if a == math.MinInt64 && b == -1 {
		return 0, ErrOverflow
	}
	return a / b, nil
}

func rem(a, b int64) (int64, error) {
	if b == 0 {
		return 0, ErrDivByZero
	}
	if b == -1 {
		return 0, nil // avoids the MinInt64 % -1 trap; the result is always 0
	}
	return a % b, nil
}

package lru

// Cache is a fixed-capacity least-recently-used cache mapping string keys to
// string values. Every operation runs in O(1) expected time.
//
// Entries live in a slice and are linked by index into a circular doubly
// linked list ordered from most to least recently used. Slot 0 is the list
// sentinel; freed slots are recycled through a free list, so the cache never
// holds more than capacity+1 slots and allocates no per-entry list nodes.
type Cache struct {
	capacity int
	index    map[string]int32
	entries  []entry
	free     []int32
}

type entry struct {
	key, value string
	prev, next int32
}

const sentinel = 0

// maxPrealloc bounds the up-front allocation so that a huge capacity paired
// with a short command stream does not reserve memory it never uses.
const maxPrealloc = 1 << 16

// NewCache returns an empty cache that holds at most capacity keys.
// It panics if capacity is less than 1.
func NewCache(capacity int) *Cache {
	if capacity < 1 {
		panic("lru: capacity must be at least 1")
	}
	hint := min(capacity, maxPrealloc)
	c := &Cache{
		capacity: capacity,
		index:    make(map[string]int32, hint),
		entries:  make([]entry, 1, hint+1),
	}
	c.entries[sentinel] = entry{prev: sentinel, next: sentinel}
	return c
}

// Len reports the number of keys held.
func (c *Cache) Len() int { return len(c.index) }

// Get returns the value stored under key and marks key as the most recently
// used. ok is false if key is absent.
func (c *Cache) Get(key string) (value string, ok bool) {
	i, ok := c.index[key]
	if !ok {
		return "", false
	}
	c.moveToFront(i)
	return c.entries[i].value, true
}

// Set stores value under key and marks key as the most recently used. If the
// cache then holds more than its capacity, the least recently used key is
// evicted.
func (c *Cache) Set(key, value string) {
	if i, ok := c.index[key]; ok {
		c.entries[i].value = value
		c.moveToFront(i)
		return
	}
	if len(c.index) >= c.capacity {
		c.remove(c.entries[sentinel].prev)
	}
	i := c.alloc()
	c.entries[i].key = key
	c.entries[i].value = value
	c.index[key] = i
	c.pushFront(i)
}

// Delete removes key and reports whether it was present.
func (c *Cache) Delete(key string) bool {
	i, ok := c.index[key]
	if !ok {
		return false
	}
	c.remove(i)
	return true
}

func (c *Cache) alloc() int32 {
	if n := len(c.free); n > 0 {
		i := c.free[n-1]
		c.free = c.free[:n-1]
		return i
	}
	c.entries = append(c.entries, entry{})
	return int32(len(c.entries) - 1)
}

// remove unlinks entry i, drops it from the index and recycles its slot.
func (c *Cache) remove(i int32) {
	c.unlink(i)
	delete(c.index, c.entries[i].key)
	c.entries[i] = entry{} // release the strings
	c.free = append(c.free, i)
}

func (c *Cache) moveToFront(i int32) {
	if c.entries[sentinel].next == i {
		return
	}
	c.unlink(i)
	c.pushFront(i)
}

func (c *Cache) unlink(i int32) {
	e := &c.entries[i]
	c.entries[e.prev].next = e.next
	c.entries[e.next].prev = e.prev
}

func (c *Cache) pushFront(i int32) {
	head := c.entries[sentinel].next
	c.entries[i].prev = sentinel
	c.entries[i].next = head
	c.entries[head].prev = i
	c.entries[sentinel].next = i
}

// Package lru simulates an LRU cache driven by commands read from its input.
//
// See the lru section of SPEC.md for the exact input and output formats.
package lru

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"strconv"
)

// MaxCapacity is the largest capacity accepted on the first input line.
const MaxCapacity = 1_000_000

// maxLine bounds the length of a single input line. Well-formed commands are
// far shorter; the limit only guards against unbounded buffering.
const maxLine = 1 << 20

// Run reads the whole lru input from r and writes the results to w.
// w is buffered by the caller, which flushes it after Run returns.
//
// The first line holds the capacity; every later line is one command.
// Blank lines and unrecognised commands are ignored.
func Run(r io.Reader, w io.Writer) error {
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 0, 64<<10), maxLine)

	if !sc.Scan() {
		return sc.Err() // empty input: nothing to do
	}
	capacity, err := parseCapacity(sc.Bytes())
	if err != nil {
		return err
	}
	cache := NewCache(capacity)

	var out []byte // reply to the current command, reused across lines
	for sc.Scan() {
		out = execute(cache, trimCR(sc.Bytes()), out[:0])
		if len(out) == 0 {
			continue
		}
		if _, err := w.Write(out); err != nil {
			return err
		}
	}
	return sc.Err()
}

// execute runs one command line against cache and appends its reply, if any,
// to out. Malformed or unknown commands produce no reply.
func execute(cache *Cache, line, out []byte) []byte {
	cmd, args := splitToken(line)
	switch string(cmd) {
	case "SET":
		key, rest := splitToken(args)
		value, _ := splitToken(rest)
		if len(key) > 0 && len(value) > 0 {
			cache.Set(string(key), string(value))
		}
	case "GET":
		if key, _ := splitToken(args); len(key) > 0 {
			if v, ok := cache.Get(string(key)); ok {
				out = append(out, v...)
			} else {
				out = append(out, "NULL"...)
			}
			out = append(out, '\n')
		}
	case "DEL":
		if key, _ := splitToken(args); len(key) > 0 {
			if cache.Delete(string(key)) {
				out = append(out, "1\n"...)
			} else {
				out = append(out, "0\n"...)
			}
		}
	case "SIZE":
		out = strconv.AppendInt(out, int64(cache.Len()), 10)
		out = append(out, '\n')
	}
	return out
}

func parseCapacity(line []byte) (int, error) {
	text := string(bytes.TrimSpace(line))
	c, err := strconv.Atoi(text)
	if err != nil || c < 1 || c > MaxCapacity {
		return 0, fmt.Errorf("invalid capacity %q: want an integer in [1, %d]", text, MaxCapacity)
	}
	return c, nil
}

// splitToken returns the first space-separated token of b and the remainder
// after the separating space.
func splitToken(b []byte) (token, rest []byte) {
	token, rest, _ = bytes.Cut(b, []byte{' '})
	return token, rest
}

func trimCR(b []byte) []byte {
	return bytes.TrimSuffix(b, []byte{'\r'})
}

// Package wordfreq prints the most frequent words of its input.
//
// See the wordfreq section of SPEC.md for the exact input and output formats.
package wordfreq

import (
	"errors"
	"io"
	"strconv"
)

// topN is the maximum number of words printed.
const topN = 10

// readBufSize is the size of the chunks read from the input.
const readBufSize = 256 << 10

// lower maps every byte to its lowercase ASCII letter, or to 0 if the byte
// is not an ASCII letter (and therefore a word separator).
var lower = func() (t [256]byte) {
	for c := 'a'; c <= 'z'; c++ {
		t[c] = byte(c)
		t[c-'a'+'A'] = byte(c)
	}
	return t
}()

// entry is a distinct word and the number of times it occurs.
type entry struct {
	word  string
	count int
}

// before reports whether a ranks ahead of b: higher count first, ties broken
// by word in ascending byte order.
func (a entry) before(b entry) bool {
	if a.count != b.count {
		return a.count > b.count
	}
	return a.word < b.word
}

// counter accumulates word frequencies.
type counter struct {
	index   map[string]int // word -> position in entries
	entries []entry
}

func newCounter() *counter {
	return &counter{index: make(map[string]int)}
}

// add records one occurrence of the lowercase word w. w is not retained.
func (c *counter) add(w []byte) {
	// The string(w) conversion in a map lookup does not allocate.
	if i, ok := c.index[string(w)]; ok {
		c.entries[i].count++
		return
	}
	s := string(w)
	c.index[s] = len(c.entries)
	c.entries = append(c.entries, entry{word: s, count: 1})
}

// top returns up to n entries in rank order.
func (c *counter) top(n int) []entry {
	best := make([]entry, 0, n+1)
	for _, e := range c.entries {
		if len(best) == n && !e.before(best[n-1]) {
			continue
		}
		// Insert e into its sorted position, dropping the last entry if full.
		i := len(best)
		for i > 0 && e.before(best[i-1]) {
			i--
		}
		best = append(best, entry{})
		copy(best[i+1:], best[i:])
		best[i] = e
		if len(best) > n {
			best = best[:n]
		}
	}
	return best
}

// Run reads the whole wordfreq input from r and writes the results to w.
// w is buffered by the caller, which flushes it after Run returns.
func Run(r io.Reader, w io.Writer) error {
	c := newCounter()
	buf := make([]byte, readBufSize)
	var word []byte // the current word, lowercased; may span reads

	for {
		n, err := r.Read(buf)
		for _, b := range buf[:n] {
			if l := lower[b]; l != 0 {
				word = append(word, l)
			} else if len(word) > 0 {
				c.add(word)
				word = word[:0]
			}
		}
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return err
		}
	}
	if len(word) > 0 {
		c.add(word)
	}

	return writeTop(w, c.top(topN))
}

// writeTop writes each entry as a "<count> <word>" line.
func writeTop(w io.Writer, entries []entry) error {
	var out []byte
	for _, e := range entries {
		out = strconv.AppendInt(out, int64(e.count), 10)
		out = append(out, ' ')
		out = append(out, e.word...)
		out = append(out, '\n')
	}
	_, err := w.Write(out)
	return err
}

package wordfreq

import (
	"strings"
	"testing"
	"testing/iotest"
)

func TestRun(t *testing.T) {
	tests := []struct {
		name, in, want string
	}{
		{"example", "The cat and the hat.", "2 the\n1 and\n1 cat\n1 hat\n"},
		{"empty", "", ""},
		{"no words", "123 _' \xff\x80 !?", ""},
		{"separators", "a1b_c'd\xc3\xa9e", "1 a\n1 b\n1 c\n1 d\n1 e\n"},
		{"case folding", "Hello hELLO HELLO", "3 hello\n"},
		{"top ten ties", "k j i h g f e d c b a a",
			"2 a\n1 b\n1 c\n1 d\n1 e\n1 f\n1 g\n1 h\n1 i\n1 j\n"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var out strings.Builder
			if err := Run(strings.NewReader(tt.in), &out); err != nil {
				t.Fatal(err)
			}
			if got := out.String(); got != tt.want {
				t.Errorf("got %q, want %q", got, tt.want)
			}
		})
	}
}

// TestRunSplitReads checks that words spanning read boundaries are kept whole.
func TestRunSplitReads(t *testing.T) {
	var out strings.Builder
	r := iotest.OneByteReader(strings.NewReader("Alpha beta ALPHA"))
	if err := Run(r, &out); err != nil {
		t.Fatal(err)
	}
	if got, want := out.String(), "2 alpha\n1 beta\n"; got != want {
		t.Errorf("got %q, want %q", got, want)
	}
}

// Command app is a suite of independent stdin-to-stdout tools.
//
// Usage:
//
//	app <subcommand>
//
// The subcommands are wordfreq, lru and calc; see SPEC.md.
package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"sort"
	"strings"

	"suite/internal/calc"
	"suite/internal/lru"
	"suite/internal/wordfreq"
)

// runFunc is the entry point shared by every subcommand. It reads its input
// from r and writes its output to w. w is buffered; the caller flushes it
// after runFunc returns.
type runFunc func(r io.Reader, w io.Writer) error

var subcommands = map[string]runFunc{
	"wordfreq": wordfreq.Run,
	"lru":      lru.Run,
	"calc":     calc.Run,
}

func main() {
	os.Exit(run(os.Args[1:]))
}

func run(args []string) int {
	if len(args) < 1 {
		usage()
		return 2
	}
	cmd, ok := subcommands[args[0]]
	if !ok {
		fmt.Fprintf(os.Stderr, "app: unknown subcommand %q\n", args[0])
		usage()
		return 2
	}

	out := bufio.NewWriterSize(os.Stdout, 64<<10)
	err := cmd(os.Stdin, out)
	if ferr := out.Flush(); err == nil {
		err = ferr
	}
	if err != nil {
		fmt.Fprintf(os.Stderr, "app %s: %v\n", args[0], err)
		return 1
	}
	return 0
}

func usage() {
	names := make([]string, 0, len(subcommands))
	for name := range subcommands {
		names = append(names, name)
	}
	sort.Strings(names)
	fmt.Fprintf(os.Stderr, "usage: app <%s>\n", strings.Join(names, "|"))
}
